const questions={ritmo:{title:'Uma pequena descoberta rítmica',symbol:'minima',text:'Nesta brincadeira, a semínima vale 1 tempo. Quanto vale a mínima?',options:['1 tempo','2 tempos','4 tempos'],answer:1,skill:'Duração das figuras',explain:'A mínima dura o dobro da semínima: aqui, são 2 tempos.',hint:'Compare as durações com o professor: a mínima ocupa dois pulsos.'},familias:{title:'Onde o violino encontra sua turma?',symbol:'🎻',text:'O som do violino nasce da vibração de…',options:['Cordas','Ar soprado dentro do tubo','Uma pele de tambor'],answer:0,skill:'Famílias dos instrumentos',explain:'As cordas vibram quando o arco passa por elas ou quando são dedilhadas.',hint:'Ouça o violino e observe o arco tocando as cordas.'},vozes:{title:'Escutando caminhos musicais',symbol:'🎶',text:'Qual situação é um exemplo de polifonia?',options:['Um grupo inteiro canta a mesma melodia','Duas melodias diferentes acontecem juntas','Todos fazem silêncio'],answer:1,skill:'Escuta de vozes simultâneas',explain:'Na polifonia, linhas melódicas diferentes acontecem simultaneamente.',hint:'Escute uma voz de cada vez no gravador e depois as duas juntas.'},historia:{title:'Investigadores da música',symbol:'🪨',text:'Sabemos exatamente em que dia a música começou?',options:['Sim: foi num dia registrado em uma partitura','Não: instrumentos antigos são pistas, mas não contam tudo','Sim: foi quando inventaram o piano'],answer:1,skill:'História e evidências',explain:'Instrumentos antigos nos dão pistas. Sons do corpo e muitas práticas não deixaram registros que permitam apontar uma data.',hint:'Retome a história: o que os objetos encontrados permitem conhecer?'}};
const names=['Clara','Miguel','Sofia','Davi'];
let courseAge=(()=>{try{const age=TeacherStorage.getItem('musiverso-course-age');return ['2–3 anos','4–5 anos','6–9 anos'].includes(age)?age:'6–9 anos'}catch{return '6–9 anos'}})();let curriculumWeek=0;let students,selected=0,lessonIndex=0,tab='aulas',active=null,feedbackTimer;
function seed(){try{students=JSON.parse(TeacherStorage.getItem('musiverso-demo-students')||'[]').map(s=>({...s,...JSON.parse(TeacherStorage.getItem('report:'+s.id)||'{}'),results:JSON.parse(TeacherStorage.getItem('report:'+s.id)||'{}').results||[],tasks:JSON.parse(TeacherStorage.getItem('report:'+s.id)||'{}').tasks||[false,false,false]}))}catch{students=[]}}
seed();
function note(type){return `<svg class="note-svg" viewBox="0 0 70 90" role="img" aria-label="${type==='minima'?'Mínima':type==='semibreve'?'Semibreve':type==='colcheia'?'Colcheia':'Semínima'}">${type==='semibreve'?'<ellipse cx="35" cy="55" rx="22" ry="13" fill="none" stroke="currentColor" stroke-width="5" transform="rotate(-15 35 55)"/>':`<ellipse cx="26" cy="67" rx="15" ry="10" fill="${type==='minima'?'white':'currentColor'}" stroke="currentColor" stroke-width="4" transform="rotate(-20 26 67)"/><path d="M39 64V13" stroke="currentColor" stroke-width="4"/>${type==='colcheia'?'<path d="M39 13C39 28 66 29 49 49C55 32 40 38 39 30Z" fill="currentColor"/>':''}`}</svg>`}
function toast(s){$('#notice').textContent=s;$('#notice').style.display='block';clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>$('#notice').style.display='none',4000)}
function studentSelect(){return `<label>Aluno <select id="studentSelect">${students.map((s,i)=>`<option value="${i}" ${selected===i?'selected':''}>${escapeDemo(s.name)}</option>`).join('')}</select></label>`}
function heading(eyebrow,title,desc){return `<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="lead">${desc}</p></div><span class="pill">Planejamento do professor</span></div>`}
function render(focus=false){stopOrff();const chosen=students[selected]?.id;seed();selected=Math.max(0,students.findIndex(s=>s.id===chosen));document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#main').innerHTML=({aulas:renderLessons,missoes:renderMission,turma:renderClass,materiais:renderMaterials,presenca:renderAttendance,iniciacao:renderInitiation,cadastro:renderRegistration}[tab]||renderLessons)();if(focus)$('#main').focus({preventScroll:true});}
function renderOlderLessons(){const l=lessons[lessonIndex];return heading('PLANEJAR · EXPLORAR · CRIAR','Um ano de descobertas musicais.','4 aulas por semana × 52 semanas = 208 aulas de 35 minutos (121 horas e 20 minutos). Cada semana reúne história, instrumentos, teoria e solfejo. Este é um acervo anual de 52 semanas; selecione as semanas adequadas ao calendário letivo.')+`<section class="hero"><div><span class="eyebrow">SUGESTÃO PARA SUA PRÓXIMA AULA</span><h2>Quatro caminhos, um ano musical</h2><p>Quatro encontros por semana: história, instrumentos, teoria e solfejo, com descoberta, experimentação, criação e retomada.</p><button class="btn light" data-lesson="${curriculumWeek*4}">Abrir aula selecionada →</button></div><div class="hero-art" aria-hidden="true">🥁 ♩</div></section><div class="section-head"><h2>Escolha um encontro</h2><small>208 aulas · 52 por área</small></div><div class="toolbar"><label>Semana do planejamento <select id="curriculumWeek">${Array.from({length:52},(_,i)=>`<option value="${i}" ${i===curriculumWeek?'selected':''}>Semana ${i+1}</option>`).join('')}</select></label><span class="pill">4 encontros · 2h20 por semana · Orff e Dalcroze</span></div><div class="lesson-grid">${lessons.map((x,i)=>i>=curriculumWeek*4&&i<curriculumWeek*4+4?`<button class="lesson-card ${i===lessonIndex?'selected':''}" data-lesson="${i}" aria-pressed="${i===lessonIndex}"><span class="lesson-icon" style="--tint:${x.tint}" aria-hidden="true">${x.icon}</span><span><span class="tiny">${x.area}</span><h3>${x.title}</h3><p>${x.goal}</p><span class="meta">${x.age} · ${x.time} · App + roda musical</span></span></button>`:'').join('')}</div><section class="panel" id="lessonPlan"><div class="plan-top"><span class="lesson-icon" style="--tint:${l.tint}" aria-hidden="true">${l.icon}</span><div><span class="tiny">SEQUÊNCIA DE AULA · ${l.time}</span><h2>${l.title}</h2><p>${l.age} · Ajuste o ritmo às necessidades da turma.</p></div></div><div class="goal"><strong>O que vamos desenvolver?</strong>${l.goal}</div><p class="note"><strong>Separe antes:</strong> ${l.materials}</p><ol class="steps">${l.steps.map(([title,desc,time],i)=>`<li><span class="step-num">${i+1}</span><div><h3>${title}</h3><p>${desc}</p></div><span class="time">${time}</span></li>`).join('')}</ol><div class="toolbar">${studentSelect()}</div><div class="actions"><button class="btn" data-try="${l.question}">▶ Realizar atividade com o aluno</button><button class="btn soft" data-print="lesson">⎙ Imprimir esta aula</button><button class="btn soft" data-go="materiais">Ver materiais →</button></div><p class="note">A pergunta é uma amostra do módulo, não uma avaliação específica de cada aula. O roteiro impresso acompanha a aula selecionada.</p><section class="goal"><strong>Acompanhamentos para o professor · inspiração Orff</strong><p>Referência: dó maior, compasso 4/4. Para improvisar, ofereça dó, ré, mi, sol e lá. Comece com dó, mi e sol; acrescente as outras notas pela escuta. O acompanhamento abaixo é uma base sugerida, não uma harmonização obrigatória de qualquer repertório.</p><div class="toolbar"><label>Base <select id="orffPattern"><option value="0">Bordão sustentado · dó–sol</option><option value="1">Bordão alternado · dó / sol</option><option value="2">Ostinato · dó–sol–mi–sol</option><option value="3">Pergunta e resposta · base com silêncio</option></select></label><label>Andamento <select id="orffTempo"><option>60</option><option selected>80</option><option>100</option></select> bpm</label></div><div id="orffScore">${orffScore(0)}</div><div class="actions"><button class="btn" data-orff-play>▶ Ouvir acompanhamento</button><button class="btn soft" data-orff-stop>■ Parar</button></div><p id="orffStatus" class="note" role="status">Exemplo sintetizado. O professor pode tocar ao vivo no piano ou em instrumentos de lâminas.</p><p class="note">Uma criança mantém a base, outra improvisa e uma terceira acompanha com movimento. Troque os papéis. Na rítmica Dalcroze, o professor também pode adaptar o acompanhamento ao movimento observado.</p></section><div class="goal"><strong>Inspiração Orff-Schulwerk</strong>${l.orff}<br><br><strong>Inspiração Dalcroze</strong>${l.dalcroze}<p class="note">Nos roteiros de teoria e solfejo, essas propostas já compõem os 35 minutos. Nas outras áreas, substitua parte da prática, sem somar tempo. São propostas autorais inspiradas nas abordagens, não um curso de certificação.</p></div><div class="sub-grid" style="margin-top:24px"><div><h3>Um jeito de adaptar</h3><p>${l.adapt}</p></div><div><h3>Uma ponte para casa</h3><p>${l.home}</p></div></div></section>`}
function renderMission(){if(!students.length)return emptyStudents();const s=students[selected],n=s.tasks.filter(Boolean).length;return heading('UMA SEMANA · PEQUENAS DESCOBERTAS','Missão: detetives do ritmo','Uma proposta de três encontros curtos ao longo de sete dias. O professor acompanha; a criança avança no próprio tempo.')+`<section class="hero"><div><span class="eyebrow">MISSÃO GUIADA · TRÊS ETAPAS</span><h2>Escutar. Criar. Compartilhar.</h2><p>Um momento no app e duas experiências fora da tela, para descobrir como as durações se combinam.</p><span class="pill" style="background:#ffffff22;color:white">Conquista simbólica: Explorador do Ritmo ⭐</span></div><div class="hero-art" aria-hidden="true">🚀</div></section><div class="toolbar">${studentSelect()}</div><section class="panel"><div class="progress-label"><span>${escapeDemo(s.name)}: caminho da semana</span><span>${n} de 3 etapas</span></div><div class="progress"><span style="width:${n/3*100}%"></span></div><div class="task-row"><span class="task-status ${s.tasks[0]?'done':''}">${s.tasks[0]?'✓':'1'}</span><div><h3>Descobrir as durações</h3><p>App · cerca de 5 min · Compare mínima e semínima e responda ao desafio.</p></div><button class="btn soft" data-try="ritmo">${s.tasks[0]?'Rever desafio':'Experimentar'}</button></div><div class="task-row"><span class="task-status ${s.tasks[1]?'done':''}">${s.tasks[1]?'✓':'2'}</span><div><h3>Compor com o corpo</h3><p>Fora da tela · cerca de 10 min · Monte quatro tempos com as cartas e toque com palmas. Um adulto observa.</p></div><button class="btn soft" data-task="1" ${s.tasks[1]?'disabled':''}>${s.tasks[1]?'Observação registrada':'Registrar realização'}</button></div><div class="task-row"><span class="task-status ${s.tasks[2]?'done':''}">${s.tasks[2]?'✓':'3'}</span><div><h3>Ensinar a alguém</h3><p>Em dupla · cerca de 5 min · Apresente sua sequência, escute a do colega e conversem sobre as durações.</p></div><button class="btn soft" data-task="2" ${s.tasks[2]?'disabled':''}>${s.tasks[2]?'Observação registrada':'Registrar realização'}</button></div>${n===3?'<div class="goal"><strong>⭐ Missão concluída!</strong>Você escutou, criou e compartilhou. Cada descoberta ganhou um lugar nesta aventura.</div>':''}<p class="note">Etapas fora da tela são registros manuais do professor ou responsável. Não há detecção automática da execução musical.</p><div class="actions"><button class="btn" data-go="turma">Ver o acompanhamento →</button><button class="btn soft" data-print="mission">⎙ Imprimir cartão da missão</button></div></section>`}
function renderClass(){if(!students.length)return emptyStudents();const practiced=students.filter(s=>s.results.length).length,complete=students.filter(s=>s.tasks.every(Boolean)).length,needs=students.filter(s=>s.results.some(r=>!r.done||r.tries>1)).length;const s=students[selected];return heading('OBSERVAR · ACOLHER · ORIENTAR','Cada criança tem seu caminho.','Um retrato simples do que foi praticado e do que merece uma nova experiência, sem transformar a aprendizagem em competição.')+`<div class="stats"><div class="stat"><strong>${practiced}/${students.length}</strong><span>Experimentaram atividades</span></div><div class="stat"><strong>${complete}/${students.length}</strong><span>Concluíram a missão</span></div><div class="stat"><strong>${needs}</strong><span>Com itens para retomar</span></div></div><section class="panel"><div class="section-head" style="margin-top:0"><h2>Turma Sementinhas</h2><small>Registros do professor · sem ranking</small></div><div class="table-wrap"><table><thead><tr><th>ALUNO</th><th>ATIVIDADES CONCLUÍDAS</th><th>MISSÃO</th><th>PRÓXIMO CUIDADO</th></tr></thead><tbody>${students.map((x,i)=>{const review=x.results.some(r=>!r.done||r.tries>1);return `<tr><td><button class="student-button" data-student="${i}" aria-label="Ver acompanhamento de ${escapeDemo(x.name)}">${escapeDemo(x.name)}</button></td><td>${x.results.filter(r=>r.done).length} de ${x.results.length} praticadas</td><td>${x.tasks.filter(Boolean).length}/3 etapas</td><td><span class="tag ${review?'warm':x.results.length?'good':''}">${review?'Retomar com apoio':x.results.length?'Ampliar descobertas':'Convidar para começar'}</span></td></tr>`}).join('')}</tbody></table></div></section><section class="panel" id="studentReport"><span class="eyebrow">OLHAR INDIVIDUAL</span><h2>${escapeDemo(s.name)}</h2><p class="note">Os resultados indicam interações com perguntas, não uma avaliação completa das habilidades musicais.</p><div class="report-list">${s.results.length?s.results.map(r=>{const q=questions[r.id];return `<article><strong>${q.skill}</strong><p>${r.done?'Resposta correta registrada':'Atividade ainda não concluída'} · ${r.tries} ${r.tries===1?'tentativa':'tentativas'} neste acompanhamento.</p>${r.tries>1||!r.done?`<div class="insight"><strong>Um próximo passo possível</strong><p>${q.hint}</p></div>`:'<span class="tag good" style="margin-top:10px">Propor uma nova situação</span>'}</article>`}).join(''):'<p class="empty">Ainda não há atividades registradas. Convide a criança para uma primeira descoberta acompanhada.</p>'}</div><div class="actions"><button class="btn" data-try="ritmo">Realizar desafio com ${escapeDemo(s.name)}</button><button class="btn soft" data-go="missoes">Ver missão de ${escapeDemo(s.name)}</button></div></section>`}
function renderMaterials(){return heading('RECORTAR · INVENTAR · BRINCAR','A música também sai da tela.','Materiais simples para usar em roda, enviar para casa ou guardar na pasta do professor. Abra a impressão e escolha papel ou PDF.')+`<div class="sub-grid"><article class="material-card"><div class="material-preview"><img src="../assets/people/mozart.jpg" alt="Retrato de Mozart" style="height:140px;width:110px;object-fit:contain"><img src="../assets/people/chiquinha.jpg" alt="Retrato de Chiquinha Gonzaga" style="height:140px;width:110px;object-fit:contain"></div><span class="badge">13 RETRATOS · 4 PÁGINAS A4</span><h2>Compositores do Musiverso Kids</h2><p>Fotografias e representações históricas do acervo do app, com nome e período. Recorte os cartões para reconhecimento, rodas de conversa e linhas do tempo.</p><button class="btn" data-print="composers">⎙ Abrir retratos para imprimir</button></article><article class="material-card"><div class="material-preview"><span class="mini-card">${note('minima')}Mínima</span><span class="mini-card">${note('seminima')}Semínima</span></div><span class="badge">6 CARTAS · 2 PÁGINAS COM ORIENTAÇÕES</span><h2>Cartas de ritmo</h2><p>Recorte, combine durações e crie sequências de quatro tempos. Inclui uma folha de criação e orientações para o professor.</p><button class="btn" data-print="rhythm">⎙ Abrir para imprimir</button></article><article class="material-card"><div class="material-preview" style="background:#eaf6ee"><span class="mini-card" style="border-color:#b5d9c6;font-size:34px">🎻</span><span class="mini-card" style="border-color:#b5d9c6;font-size:34px">🥁</span></div><span class="badge">6 CARTAS + 3 ETIQUETAS</span><h2>Famílias em roda</h2><p>Cartões com nome e descrição do som: violino, violão, flauta, clarinete, tambor e chocalho. Agrupe e explique suas escolhas.</p><button class="btn green" data-print="families">⎙ Abrir para imprimir</button></article><article class="material-card"><div class="material-preview" style="background:#fff3d9"><span style="font-size:68px" aria-hidden="true">🚀</span></div><span class="badge">1 PÁGINA · ACOMPANHAMENTO EM CASA</span><h2>Passaporte da missão</h2><p>Uma proposta de três etapas com espaço para nome, marcações e uma descoberta contada pela criança.</p><button class="btn" data-print="mission">⎙ Abrir para imprimir</button></article><article class="material-card"><div class="material-preview"><span style="font-size:68px" aria-hidden="true">📋</span></div><span class="badge">PLANO DO ENCONTRO SELECIONADO</span><h2>Roteiro do professor</h2><p>Objetivo, materiais, etapas, adaptação e proposta para casa. Aula selecionada: <strong>${lessons[lessonIndex].title}</strong>.</p><button class="btn" data-print="lesson">⎙ Imprimir roteiro</button></article></div><p class="note">Use os materiais para apoiar as atividades presenciais e adapte a proposta à faixa etária.</p>`}
function openActivity(id){if(!students.length){toast('Cadastre um aluno em Alunos e horários.');return}const q=questions[id];active={id,student:selected,finished:false};const s=students[selected];$('#activityBody').innerHTML=`<h2>${q.title}</h2><p class="answer-person">Você está experimentando como ${escapeDemo(s.name)}</p><div class="question-symbol" aria-hidden="true">${q.symbol==='minima'?note('minima'):q.symbol}</div><p><strong>${q.text}</strong></p><div class="options">${q.options.map((o,i)=>`<button class="option" data-answer="${i}">${o}</button>`).join('')}</div><p id="feedback" role="status" aria-live="polite">Escolha uma resposta. O resultado aparecerá no acompanhamento.</p><div id="afterAnswer" class="actions"></div>`;$('#activity').showModal();}
function answer(index,button){if(!active||active.finished)return;const {id,student}=active,q=questions[id],s=students[student];let result=s.results.find(r=>r.id===id);if(!result){result={id,tries:0,done:false};s.results.push(result)}result.tries++;if(index===q.answer){active.finished=true;result.done=true;if(id==='ritmo')s.tasks[0]=true;button.classList.add('correct');document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);$('#feedback').textContent='Muito bem! '+q.explain;$('#afterAnswer').innerHTML='<button class="btn" data-report>Ver resultado no painel →</button>';}else{button.classList.add('wrong');button.disabled=true;$('#feedback').textContent='Vamos tentar de outro jeito? '+q.hint}saveStudentReport(s);render();}
function sheetHeader(title){return `<div class="sheet-header"><strong>MUSIVERSO KIDS · MATERIAL DO PROFESSOR</strong><span>Professor · 6–9 anos</span></div><h1 style="font-size:26px">${title}</h1>`}
function printMaterial(type){const l=lessons[lessonIndex];let html='';if(type==='composers'){html=`${sheetHeader('Compositores do Musiverso Kids')}<p>Recorte os cartões. Retratos e representações históricas do acervo do app; nem todas as imagens são fotografias.</p><div class="composer-print-grid">${composerPortraitCards()}</div><p class="print-help">Proposta: escolha um retrato, encontre o compositor no app e escute uma obra com a turma.</p>`}else if(type==='rhythm'){const cards=[['semibreve','Semibreve','4 tempos'],['minima','Mínima','2 tempos'],['minima','Mínima','2 tempos'],['seminima','Semínima','1 tempo'],['seminima','Semínima','1 tempo'],['colcheia','Colcheia','½ tempo']];html=`<div class="sheet-page">${sheetHeader('Cartas de ritmo')}<p>Recorte nas linhas pontilhadas. Nesta atividade, a semínima vale 1 tempo.</p><div class="print-cards" style="margin-top:20px">${cards.map(([t,n,v])=>`<div class="print-card">${note(t)}<h3>${n}</h3><p>${v}</p></div>`).join('')}</div><p class="print-help"><strong>Para o professor:</strong> comece com semínimas e mínimas. Amplie com a semibreve e com pares de colcheias. Imprima mais cópias para montar combinações diferentes. Os valores em tempos dependem da unidade adotada; aqui, a referência é a semínima.</p></div><div class="sheet-page">${sheetHeader('Minha composição de quatro tempos')}<p>Nome: <span class="write-line"></span> Data: <span class="write-line"></span></p><h2>1. Um ritmo com quatro tempos</h2><p>Desenhe ou cole as figuras. Confira a soma com o professor.</p><div class="work-box" style="height:130px"></div><h2>2. Outra combinação, a mesma duração</h2><div class="work-box" style="height:130px"></div><h2>3. Agora, faça música!</h2><p>Uma pessoa marca o pulso; a outra toca a sequência com palmas. Troquem os papéis.</p><p class="print-help">Observe: mantém a pulsação? Sustenta as notas longas? Explica sua combinação? Registre com palavras, sem comparar crianças.</p></div>`}else if(type==='families'){const instruments=[['Violino','Cordas vibram, geralmente tocadas com um arco.'],['Violão','Cordas vibram quando são dedilhadas ou tocadas.'],['Flauta','O sopro põe o ar em vibração.'],['Clarinete','O sopro faz uma palheta vibrar e põe o ar do tubo em vibração.'],['Tambor','Uma pele ou membrana vibra quando é percutida.'],['Chocalho','Pequenas peças batem dentro de um recipiente quando ele é sacudido.']];html=`${sheetHeader('Famílias em roda')}<p>Recorte e agrupe. Conte como cada instrumento produz seu som.</p><div class="print-cards" style="margin-top:20px">${instruments.map(([n,d])=>`<div class="print-card"><h3>${n}</h3><p style="margin-top:15px">${d}</p><p style="margin-top:20px">Desenhe ou imite o instrumento.</p></div>`).join('')}${['CORDAS','SOPRO','PERCUSSÃO'].map(n=>`<div class="print-card" style="min-height:65px"><strong>${n}</strong></div>`).join('')}</div><p class="print-help">Professor: cordas — violino e violão; sopro — flauta e clarinete; percussão — tambor e chocalho. Mostre imagens ou instrumentos reais para apoiar a exploração.</p>`}else if(type==='mission'){html=`${sheetHeader('Passaporte: detetives do ritmo')}<p>Nome: <span class="write-line"></span></p><p>Minha semana: de <span class="write-line"></span> até <span class="write-line"></span></p><h2>□ 1. Escutar e descobrir</h2><p>Com um adulto, compare mínima e semínima no app. Nesta atividade, a semínima vale 1 tempo e a mínima vale 2.</p><h2>□ 2. Criar fora da tela</h2><p>Monte uma sequência de quatro tempos com as cartas e execute com palmas. Peça a alguém para marcar a pulsação.</p><h2>□ 3. Compartilhar</h2><p>Mostre sua sequência a outra pessoa. Escute a dela e conversem sobre os sons longos e curtos.</p><h2>Minha descoberta da semana</h2><div class="work-box" style="height:150px">Desenhe ou conte para um adulto escrever.</div><p class="print-help">Professor ou responsável: acompanhe a experiência e marque apenas o que foi realizado. A atividade é um convite à descoberta, não uma competição.</p>`}else{html=`${sheetHeader(l.title)}<p>${l.age} · ${l.time} · ${l.area}</p><div class="goal"><strong>Objetivo</strong>${l.goal}</div><p><strong>Materiais:</strong> ${l.materials}</p><p><strong>No app:</strong> ${l.app}</p>${l.steps.map(([t,d,m],i)=>`<h2 style="font-size:20px">${i+1}. ${t} · ${m}</h2><p>${d}</p>`).join('')}<h2>Acompanhamento sugerido ao professor</h2><p>4/4, semínima = 80 bpm. Bordão sustentado: dó3 + sol3 juntos, duração de quatro tempos; repetir. Alternativa: dó3 no tempo 1 e sol3 no tempo 3, cada um com dois tempos. Melodia: dó, ré, mi, sol e lá em região confortável.</p><p>Comece com a base; acrescente uma improvisação curta. Faça pausas para escutar e alternar papéis. Adapte a base à canção escolhida: não a aplique automaticamente a qualquer melodia.</p><p class="print-help"><strong>Orff-Schulwerk:</strong> ${l.orff}</p><p class="print-help"><strong>Dalcroze:</strong> ${l.dalcroze}</p><p class="print-help"><strong>Adaptação:</strong> ${l.adapt}</p><p class="print-help"><strong>Para casa:</strong> ${l.home}</p>`}$('#printSheet').innerHTML=html;let viewer=$('#materialViewer');if(!viewer){viewer=document.createElement('dialog');viewer.id='materialViewer';viewer.className='print-preview';document.body.append(viewer)}viewer.innerHTML='<div class="modal-top"><strong>Prévia do material</strong><button class="icon-button" data-close-print aria-label="Fechar prévia">✕</button></div><div class="actions"><button class="btn" data-send-print>⎙ Imprimir / salvar PDF</button></div><div class="paper-preview">'+html+'</div>';viewer.showModal();if(type==='composers'){const button=viewer.querySelector('[data-send-print]');button.disabled=true;button.textContent='Carregando retratos…';const imgs=[...viewer.querySelectorAll('img'),...document.querySelectorAll('#printSheet img')];Promise.all(imgs.map(img=>img.decode().catch(()=>null))).then(()=>{const failed=imgs.some(img=>!img.naturalWidth);button.disabled=failed;button.textContent=failed?'Imagens indisponíveis. Feche e tente novamente.':'⎙ Imprimir / salvar PDF';})}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close-print')){$('#materialViewer').close()}else if(b.hasAttribute('data-send-print')){window.print()}else if(b.dataset.tab||b.dataset.go){tab=b.dataset.tab||b.dataset.go;location.hash=tab;render(true);window.scrollTo({top:0,behavior:'instant'})}else if(b.dataset.lesson!==undefined){lessonIndex=Number(b.dataset.lesson);render();$('#lessonPlan').scrollIntoView({behavior:'smooth',block:'start'});$('#lessonPlan').setAttribute('tabindex','-1');$('#lessonPlan').focus({preventScroll:true})}else if(b.dataset.try){openActivity(b.dataset.try)}else if(b.dataset.answer!==undefined){answer(Number(b.dataset.answer),b)}else if(b.hasAttribute('data-report')){$('#activity').close();selected=active.student;tab='turma';location.hash=tab;render(true);$('#studentReport').scrollIntoView({behavior:'smooth'})}else if(b.dataset.student!==undefined){selected=Number(b.dataset.student);render();$('#studentReport').scrollIntoView({behavior:'smooth'})}else if(b.dataset.task){students[selected].tasks[Number(b.dataset.task)]=true;saveStudentReport(students[selected]);render();toast('Realização registrada para '+students[selected].name+' no acompanhamento.')}else if(b.dataset.print){printMaterial(b.dataset.print)}else if(b.id==='closeActivity'){$('#activity').close()}else if(b.id==='reset'){seed();selected=0;lessonIndex=0;render();toast('Demonstração reiniciada.')}});
document.addEventListener('change',e=>{if(e.target.id==='studentSelect'){selected=Number(e.target.value);if(tab==='presenca')$('#attendanceRows').innerHTML=attendanceRows();else render()}});
window.addEventListener('hashchange',()=>{const t=location.hash.slice(1);if(['aulas','missoes','turma','materiais','presenca','iniciacao','cadastro'].includes(t)&&t!==tab){tab=t;render(true)}});
if(['aulas','missoes','turma','materiais','presenca','iniciacao','cadastro'].includes(location.hash.slice(1)))tab=location.hash.slice(1);render();

function attendanceData(){try{return JSON.parse(TeacherStorage.getItem('musiverso-teacher-demo-attendance')||'{}')}catch{return {}}}
function renderAttendance(){const today=[new Date().getFullYear(),String(new Date().getMonth()+1).padStart(2,'0'),String(new Date().getDate()).padStart(2,'0')].join('-');return heading('DIÁRIO DO PROFESSOR','Presença em cada encontro','Registre a presença dos seus alunos e exporte o diário como CSV. Os dados são sincronizados com sua conta.')+`<section class="panel"><div class="toolbar"><label>Data <input type="date" id="attendanceDate" value="${today}"></label><label>Encontro <select id="attendanceLesson"><option value="historia">História</option><option value="instrumentos">Instrumentos</option><option value="teoria">Teoria</option><option value="solfejo">Solfejo</option></select></label><label>Modalidade <select id="attendanceMode"><option value="turma">Turma Sementinhas</option><option value="individual">Aula individual</option></select></label>${studentSelect()}</div><p class="note">Na turma, marque os alunos participantes. Na aula individual, marque apenas o aluno selecionado. Escolha a data e toque em Carregar para rever um registro anterior.</p><div class="actions"><button class="btn soft" id="loadAttendance">Carregar data</button></div><div id="attendanceRows">${attendanceRows()}</div><div class="actions"><button class="btn" id="saveAttendance">Salvar presença</button><button class="btn soft" id="exportAttendance">Exportar diário CSV</button></div><p id="attendanceMessage" role="status" class="note">Confira o indicador de sincronização no topo antes de fechar. Você também pode exportar uma cópia do diário.</p></section>`}
function attendanceRows(){const date=$('#attendanceDate')?.value||[new Date().getFullYear(),String(new Date().getMonth()+1).padStart(2,'0'),String(new Date().getDate()).padStart(2,'0')].join('-'),mode=$('#attendanceMode')?.value||'turma',data=attendanceData();return students.map((s,i)=>{if(mode==='individual'&&i!==selected)return '';if(mode==='turma'&&s.mode==='individual')return '';const value=data[date+'|'+($('#attendanceLesson')?.value||'historia')+'|'+mode+'|'+s.id]?.status||'';return `<div class="task-row"><strong>${escapeDemo(s.name)}</strong><div></div><label><span class="sr-only">Presença de ${escapeDemo(s.name)}</span><select data-attendance="${i}">${[['','Não marcado'],['presente','Presente'],['falta','Falta'],['justificada','Falta justificada']].map(([v,n])=>`<option value="${v}" ${value===v?'selected':''}>${n}</option>`).join('')}</select></label></div>`}).join('')}
document.addEventListener('change',e=>{if(['attendanceMode','attendanceDate','attendanceLesson'].includes(e.target.id))$('#attendanceRows').innerHTML=attendanceRows()});
document.addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(id==='loadAttendance')$('#attendanceRows').innerHTML=attendanceRows();if(id==='saveAttendance'){const date=$('#attendanceDate').value,mode=$('#attendanceMode').value;if(!date){$('#attendanceMessage').textContent='Selecione a data da aula.';return}const data=attendanceData();document.querySelectorAll('[data-attendance]').forEach(el=>{const i=el.dataset.attendance,key=date+'|'+($('#attendanceLesson')?.value||'historia')+'|'+mode+'|'+students[i].id;if(el.value)data[key]={date,lesson:$('#attendanceLesson').value,mode,name:students[i].name,status:el.value};else delete data[key]});try{TeacherStorage.setItem('musiverso-teacher-demo-attendance',JSON.stringify(data));$('#attendanceMessage').textContent='Presença registrada; confira a sincronização no topo. Data: '+date.split('-').reverse().join('/')+'.'}catch{$('#attendanceMessage').textContent='Não foi possível salvar neste navegador. Verifique se o armazenamento está permitido.'}}if(id==='exportAttendance'){const rows=Object.values(attendanceData()).sort((a,b)=>a.date.localeCompare(b.date));if(!rows.length){toast('Ainda não há presenças salvas.');return}const csv='\uFEFFData;Encontro;Modalidade;Aluno;Presença\n'+rows.map(r=>[r.date,r.lesson||'historia',r.mode,r.name,r.status].map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(';')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='presencas-musiverso.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});

document.addEventListener('change',e=>{if(e.target.id==='curriculumWeek'){curriculumWeek=Number(e.target.value);lessonIndex=curriculumWeek*4;render()}});

function orffScore(i){return ['<p><b>Bordão sustentado:</b> dó3 + sol3 juntos no tempo 1. Sustente por 4 tempos e repita. Mão esquerda: dó3; direita: sol3.</p>','<p><b>Bordão alternado:</b> dó3 nos tempos 1–2; sol3 nos tempos 3–4. Cada nota dura 2 tempos. Alterne as mãos ou dois instrumentos.</p>','<p><b>Ostinato:</b> dó3 → sol3 → mi3 → sol3. Uma nota em cada tempo. Repita enquanto a turma improvisa uma frase curta.</p>','<p><b>Espaço para responder:</b> dó3 + sol3 juntos por 2 tempos; silêncio por 2 tempos. A criança responde no espaço, e o grupo recomeça junto.</p>'][i]+'<p class="note">Convenção de altura: dó4 = dó central. Use outra oitava se o instrumento ou a voz pedir. Cada exemplo repete um compasso.</p>'}
function stopOrff(){clearInterval(orffTimer);orffTimer=null;orffNodes.forEach(n=>{try{n.stop()}catch{}});orffNodes=[];if(orffContext){orffContext.close().catch(()=>{});orffContext=null}const el=$('#orffStatus');if(el)el.textContent='Acompanhamento interrompido.'}
async function startOrff(){stopOrff();const C=window.AudioContext||window.webkitAudioContext;if(!C){$('#orffStatus').textContent='Áudio indisponível neste navegador. Use as notas indicadas para tocar ao vivo.';return}const c=new C();orffContext=c;try{await c.resume();if(orffContext!==c)return;const pattern=Number($('#orffPattern').value),beat=60/Number($('#orffTempo').value);let next=c.currentTime+.1;function note(midi,t,d){const o=c.createOscillator(),g=c.createGain();o.type='triangle';o.frequency.value=440*Math.pow(2,(midi-69)/12);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.12,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+Math.max(.05,d-.03));o.connect(g).connect(c.destination);o.start(t);o.stop(t+d);orffNodes.push(o);o.onended=()=>{orffNodes=orffNodes.filter(n=>n!==o);o.disconnect();g.disconnect()}}
function schedule(){while(next<c.currentTime+.3){if(pattern===0){note(48,next,beat*4*.95);note(55,next,beat*4*.95)}if(pattern===1){note(48,next,beat*1.9);note(55,next+beat*2,beat*1.9)}if(pattern===2)[48,55,52,55].forEach((n,i)=>note(n,next+i*beat,beat*.9));if(pattern===3){note(48,next,beat*1.9);note(55,next,beat*1.9)}next+=beat*4}}schedule();orffTimer=setInterval(schedule,100);$('#orffStatus').textContent='Reproduzindo em repetição. Toque em Parar para encerrar.'}catch{stopOrff();$('#orffStatus').textContent='Não foi possível iniciar o som. Tente novamente.'}}
document.addEventListener('click',e=>{if(e.target.closest('[data-orff-play]'))startOrff();if(e.target.closest('[data-orff-stop]'))stopOrff()});document.addEventListener('change',e=>{if(e.target.id==='orffPattern'){stopOrff();$('#orffScore').innerHTML=orffScore(Number(e.target.value))}if(e.target.id==='orffTempo')stopOrff()});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopOrff()});window.addEventListener('pagehide',stopOrff);

function renderLessons(){const selector=`<div class="toolbar age-choice"><label>Faixa etária do aluno ou turma <select id="courseAge">${['2–3 anos','4–5 anos','6–9 anos'].map(a=>`<option ${a===courseAge?'selected':''}>${a}</option>`).join('')}</select></label></div>`;if(courseAge!=='6–9 anos'){preschoolAge=courseAge;return selector+renderInitiation()}return selector+renderOlderLessons()}
document.addEventListener('change',e=>{if(e.target.id==='courseAge'){courseAge=e.target.value;try{TeacherStorage.setItem('musiverso-course-age',courseAge)}catch{}render()}});

const printComposers=[{"id": "hildegard", "name": "Hildegard von Bingen", "era": "Idade Média"}, {"id": "josquin", "name": "Josquin des Prez", "era": "Renascimento"}, {"id": "bach", "name": "Johann Sebastian Bach", "era": "Barroco"}, {"id": "vivaldi", "name": "Antonio Vivaldi", "era": "Barroco"}, {"id": "mozart", "name": "Wolfgang Amadeus Mozart", "era": "Classicismo"}, {"id": "haydn", "name": "Joseph Haydn", "era": "Classicismo"}, {"id": "beethoven", "name": "Ludwig van Beethoven", "era": "Classicismo e Romantismo"}, {"id": "schubert", "name": "Franz Schubert", "era": "Romantismo"}, {"id": "chopin", "name": "Frédéric Chopin", "era": "Romantismo"}, {"id": "clara", "name": "Clara Schumann", "era": "Romantismo"}, {"id": "chiquinha", "name": "Chiquinha Gonzaga", "era": "Brasil"}, {"id": "pixinguinha", "name": "Pixinguinha", "era": "Brasil"}, {"id": "villa-lobos", "name": "Heitor Villa-Lobos", "era": "Brasil"}];
function composerPortraitCards(){return printComposers.map(p=>`<article class="composer-print-card"><img src="../assets/people/${p.id}.jpg" alt="Retrato de ${p.name}" width="320" height="360"><h2>${p.name}</h2><p>${p.era}</p></article>`).join('')}

function emptyStudents(){return heading('SEUS ALUNOS','Vamos começar pela sua turma?','Cadastre o primeiro aluno para registrar atividades, missões e presenças.')+'<button class="btn" data-go="cadastro">Cadastrar aluno</button>'}
function saveStudentReport(s){TeacherStorage.setItem('report:'+s.id,JSON.stringify({results:s.results,tasks:s.tasks}))}

window.addEventListener('teacher-refreshed',()=>render());
